import { listJobsByStatus } from '../store/jobs';

// Claimable = queued AND not wait-mode. Wait-mode jobs are driven by an external trigger, not the
// poller, so they are filtered out here.
export async function getClaimableJobIds(): Promise<string[]> {
  const queued = await listJobsByStatus('queued');
  return queued.filter((j) => j.startMode !== 'wait').map((j) => j.id);
}

