export function scanRoots(): string[] {
  if (!existsSync(CONFIG)) return ['.'];
  const c = JSON.parse(readFileSync(CONFIG, 'utf8')); // a malformed config must throw, not scan-all
  if (!Array.isArray(c.scanRoots) || c.scanRoots.length === 0) return ['.'];
  return c.scanRoots;
}

