import { useEffect } from 'react';

// Subscribes to a window event for the lifetime of the component; re-subscribes whenever
// eventName or the handler identity changes.
export function useWindowEvent(eventName: string, handler: (event: Event) => void): void {
  useEffect(() => {
    window.addEventListener(eventName, handler);
    return () => window.removeEventListener(eventName, handler);
  }, [eventName, handler]);
}

