import { execFileSync } from 'node:child_process';

// Creates a new local branch and pushes it upstream, rejecting first if a remote branch of the
// same name is already in use.
export function shipBranch(branchName: string): void {
  execFileSync('git', ['checkout', '-b', branchName]);
  if (remoteBranchExists(branchName)) {
    throw new Error(`remote branch already exists: origin/${branchName}`);
  }
  execFileSync('git', ['push', '-u', 'origin', branchName]);
}

// git ls-remote --exit-code exits 0 on a match, 2 on "no match", and anything else on a genuine
// lookup failure (network, auth, timeout) — those three cases are not interchangeable.
function remoteBranchExists(branchName: string): boolean {
  try {
    execFileSync('git', ['ls-remote', '--exit-code', '--heads', 'origin', branchName]);
    return true;
  } catch (err) {
    if ((err as { status?: number }).status === 2) return false;
    throw new Error(`could not verify remote branch does not exist: origin/${branchName}`);
  }
}

