  clientSecret: string;
  accountId: string;
}

export async function sendWebhook(auth: WebhookAuth, payload: unknown): Promise<void> {
  if (!auth.clientId || !auth.clientSecret || !auth.accountId) {
    throw new Error('webhook client rejected incomplete auth');
  }
  await fetch('/internal/dispatch', {
    method: 'POST',
    headers: { 'x-client-id': auth.clientId },
    body: JSON.stringify(payload),
  });
}

