let state: Record<string, 'pass' | 'fail'> = {};

// Judge tool calls persist each item's outcome here as they run, so a crashed attempt can leave
// partial results behind for whatever runs next.
export function recordItem(name: string, outcome: 'pass' | 'fail'): void {
  state[name] = outcome;
}

export function resetChecklist(): void {
  state = {};
}

export function verifyChecklist(): boolean {
  return Object.values(state).every((v) => v === 'pass');
}

