import { resetChecklist, verifyChecklist } from './checklist-store';

// Runs the first-pass judge; strict (ship) callers get one retry on a transient outage so a
// flaky API call doesn't fail the whole run.
export async function runFirstPass(
  opts: JudgeOpts,
  retryOnOutage: boolean,
): Promise<boolean | null> {
  let result = await execJudge(opts);
  if (result === null && retryOnOutage) {
    resetChecklist();
    result = await execJudge(opts);
  }
  if (result === null) return null;
  return verifyChecklist();
}

