import { existsSync, readFileSync } from 'node:fs';

// Stop-hook guard: skip the sweep check unless the consumer repo has a sweep config.
// Recognizes every config form sweep documents, including the dotted/.js/package.json forms.
export function hasSweepConfig(cwd: string): boolean {
  const files = [
    'sweep.json',
    'sweep.jsonc',
    '.sweep.json',
    '.sweep.jsonc',
    'sweep.ts',
    'sweep.js',
    'sweep.config.ts',
    'sweep.config.js',
  ];
  if (files.some((f) => existsSync(`${cwd}/${f}`))) return true;
  try {
    const pkg = JSON.parse(readFileSync(`${cwd}/package.json`, 'utf8'));
    return pkg.sweep !== undefined;
  } catch {
    return false;
  }
}

