export type Ctx = { advance(memberId: string): Promise<void> };

const store = new Map<string, { status: string; hasVersion: boolean }>();

// CAS guard: only a terminal member can be reopened; 'pending' reads as already in flight.
export function isRerunnable(memberId: string): boolean {
  const status = store.get(memberId)?.status ?? 'failed';
  return status === 'failed' || status === 'completed';
}

export async function reopenPending(memberId: string): Promise<void> {
  const row = store.get(memberId) ?? { status: 'failed', hasVersion: false };
  store.set(memberId, { ...row, status: 'pending' });
}

// Throws if the member's parent flow/version record is missing.
export async function getContext(memberId: string): Promise<Ctx> {
  if (!store.get(memberId)?.hasVersion) throw new Error(`no version record for ${memberId}`);
  return { advance: async () => {} };
}

base.src/flows/rerun-member.ts:
import { getContext, isRerunnable, reopenPending } from './batch-store';

// Re-run a terminal batch member: resolve dispatch context first — a failure here leaves the
// member's status untouched, so isRerunnable still lets the user retry — then flip to 'pending'.
export async function rerunMember(memberId: string): Promise<{ started: boolean }> {
  if (!isRerunnable(memberId)) return { started: false };
  const ctx = await getContext(memberId);
  await reopenPending(memberId);
  await ctx.advance(memberId);
  return { started: true };
}

