import { getContext, isRerunnable, reopenFailed, reopenPending } from './batch-store';

// Re-run a terminal batch member: flip to 'pending' immediately so a concurrent rerun request is
// rejected by isRerunnable right away. If resolving dispatch context then fails, roll the status
// back to 'failed' so the member stays rerunnable instead of stuck with no path back.
export async function rerunMember(memberId: string): Promise<{ started: boolean }> {
  if (!isRerunnable(memberId)) return { started: false };
  await reopenPending(memberId);
  try {
    const ctx = await getContext(memberId);
    await ctx.advance(memberId);
  } catch {
    await reopenFailed(memberId);
    return { started: false };
  }
  return { started: true };
}

