import { getBatchMember, setBatchMemberStatus } from '../store/batches';

// Flips a batch member's bookkeeping to dispatched so its stage isn't treated as settled once
// the resumed task starts producing output again.
export async function reopenBatchMember(flowRunId: string): Promise<void> {
  const member = await getBatchMember(flowRunId);
  if (!member) return;
  await setBatchMemberStatus(flowRunId, 'dispatched');
}

base.api/tasks/retry.ts:
import { setTaskStatusIf, getTask } from '../store/tasks';

// Server-side retry: flip a failed/parked task back to running with a CAS so a stale attempt
// can't be resumed twice by two concurrent requests.
export async function retryTask(taskId: string): Promise<void> {
  const task = await getTask(taskId);
  if (!task || (task.status !== 'failed' && task.status !== 'parked')) return;
  await setTaskStatusIf(taskId, ['failed', 'parked'], 'running');
}

