// Tolerant reader: cloud-mirrored rows can carry `result` as a JSON STRING (createChatForTask
// parses the same shape). Malformed strings degrade to `{}`.
export function parseResultRecord(result: unknown): Record<string, unknown> {
  if (typeof result === 'string') {
    try {
      const parsed = JSON.parse(result);
      return parsed && typeof parsed === 'object' ? (parsed as Record<string, unknown>) : {};
    } catch {
      return {};
    }
  }
  return result && typeof result === 'object' ? (result as Record<string, unknown>) : {};
}

