import { parseResultRecord } from './result-record';

// Park a running task: merge routing metadata into its stored result without losing the fields
// (chatId/subChatId/startMode) that a resumed session needs to find its way back to the chat.
export function buildParkedResult(rawResult: unknown, note: string): Record<string, unknown> {
  const existing = parseResultRecord(rawResult);
  return { ...existing, parkedNote: note };
}

