import { sendMessage, isSocketConnected } from './socket';

let pendingChatRetry: string | null = null;

// Existing Retry flow: only proceeds when the socket is connected, and never touches the
// marker until the resend below has actually gone out.
export async function retryChat(message: string): Promise<void> {
  if (!isSocketConnected()) return notifySendBlocked();
  await sendMessage(message);
  pendingChatRetry = null;
}

function notifySendBlocked(): void {
  console.warn('send blocked: socket disconnected');
}

