// Carry on beside Retry: wakes a parked session with a hidden follow-up message. Follows the
// same guard as Retry -- the marker is snapshotted and only durably cleared once the wake
// message is accepted, and is put back if the send is rejected.
export async function carryOnChat(message: string): Promise<void> {
  if (!isSocketConnected()) return notifySendBlocked();
  const previous = pendingChatRetry;
  pendingChatRetry = null;
  try {
    await sendMessage(message);
  } catch (err) {
    pendingChatRetry = previous;
    throw err;
  }
}

function notifySendBlocked(): void {
  console.warn('send blocked: socket disconnected');
}

