import { appendLine, readLines, withFileLock } from './store';
import { deepValidate } from './validate';

// Registry intake: one line per entry, ids unique.
export async function registerEntry(entry: { id: string }): Promise<boolean> {
  await deepValidate(entry);
  return withFileLock('registry.jsonl', async () => {
    const existing = await readLines('registry.jsonl');
    if (existing.some((l) => JSON.parse(l).id === entry.id)) return false;
    await appendLine('registry.jsonl', JSON.stringify(entry));
    return true;
  });
}

