staged.api/rows/reserved.ts:
export interface Row {
  id: string;
  score: number;
  reserved: boolean;
}

// A row's reserved flag is decided exactly once, at intake. Downstream comparisons key on it
// staying fixed for the row's lifetime.
export function assignReserved(row: Omit<Row, 'reserved'>): Row {
  return { ...row, reserved: row.score >= 0.8 };
}

export function enforceReservedFloor(rows: Row[], floor: number): Row[] {
  let reserved = rows.filter((r) => r.reserved).length;
  for (const r of rows) {
    if (reserved >= floor) break;
    if (!r.reserved) {
      r.reserved = true;
      reserved += 1;
    }
  }
  return rows;
}

base.api/events/export.ts:
export interface LensEvent {
  runId: string;
  check: string;
  disposition: 'blocking' | 'waived';
}

const keyOf = (e: LensEvent) => `${e.runId}/${e.check}`;

// Exports one record per keyed event for the downstream store (last write per key wins).
export function exportRecords(events: LensEvent[]): Map<string, { kind: string }> {
  const out = new Map<string, { kind: string }>();
  for (const e of events) out.set(keyOf(e), { kind: 'failure' });
  return out;
}

