  const out = new Map<string, { kind: string }>();
  for (const e of events) {
    if (e.disposition === 'blocking') out.set(keyOf(e), { kind: 'failure' });
  }
  for (const e of events) {
    if (e.disposition === 'waived') out.set(keyOf(e), { kind: 'waiver' });
  }
  return out;
}

