import { lintEntry } from './lint';

export interface Entry {
  id: string;
  payload: { fields: Record<string, string> };
}

// Collects every problem with a submitted entry (never throws to the caller).
export function checkEntry(entry: Entry): string[] {
  const problems: string[] = [];
  try {
    lintEntry(entry);
  } catch (e) {
    problems.push(e instanceof Error ? e.message : String(e));
  }
  if (problems.length === 0) {
    if (Object.values(entry.payload.fields).some((v) => v.length === 0)) {
      problems.push('empty field value');
    }
  }
  return problems;
}

